import React, { useState, useContext } from 'react';
import Form from '@rjsf/core';
import validator from '@rjsf/validator-ajv8';
import axios from 'axios';
import { ethers } from 'ethers'; // Import ethers để gọi ví
import { Web3Context } from '../contexts/Web3Context';
import { UIContext } from '../App'; 

const schema = {
  title: " ",
  type: "object",
  required: ["topic", "question_content", "correct_option_index"],
  properties: {
    topic: { type: "string", title: "CHỦ ĐỀ", enum: ["Grammar", "Vocabulary", "Reading", "IELTS"] },
    question_content: { type: "string", title: "NỘI DUNG CÂU HỎI", minLength: 10 },
    options: { 
      type: "array", title: "CÁC LỰA CHỌN (4 ĐÁP ÁN)", minItems: 4, maxItems: 4, 
      items: { type: "string", default: "" } 
    },
    correct_option_index: { 
      type: "integer", title: "ĐÁP ÁN ĐÚNG (0-3)", enum: [0, 1, 2, 3],
      enumNames: ["Đáp án 1", "Đáp án 2", "Đáp án 3", "Đáp án 4"] 
    },
    stake_amount: { type: "integer", title: "MỨC CƯỢC (TOKEN)", default: 5 }
  }
};

const uiSchema = {
  question_content: { "ui:widget": "textarea", "ui:options": { rows: 4, placeholder: "Nhập câu hỏi tiếng Anh của bạn..." } },
  stake_amount: { "ui:widget": "updown" }
};

const CreatorStudio = () => {
  const { currentAccount } = useContext(Web3Context);
  const { showToast } = useContext(UIContext); // Lấy hàm hiển thị thông báo
  
  const [status, setStatus] = useState("idle"); 
  const [logs, setLogs] = useState([]);

  const addLog = (msg) => setLogs(prev => [...prev, msg]);

  const onSubmit = async ({ formData }) => {
    if (!currentAccount) {
        showToast('error', "Vui lòng kết nối ví trước!");
        return;
    }
    
    setStatus("processing");
    setLogs([]); // Reset log
    addLog(`⏳ Đang khởi tạo giao dịch...`);

    try {
      // --- BƯỚC 1: TƯƠNG TÁC VÍ THẬT (SIGNATURE) ---
      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner();
      
      addLog("🔐 Vui lòng ký xác nhận trên MetaMask...");
      
      // Ký một tin nhắn để xác thực chủ sở hữu (Không tốn gas)
      const message = `Tôi xác nhận đăng bài tập này lên Web3Learn vào lúc ${new Date().toLocaleString()}`;
      const signature = await signer.signMessage(message);
      
      addLog("✅ Đã ký xác thực! Đang gửi AI duyệt...");

      // --- BƯỚC 2: GỬI LÊN SERVER ---
      const payload = { 
          ...formData, 
          creator_address: currentAccount,
          signature: signature // Gửi kèm chữ ký
      };

      const res = await axios.post('http://localhost:5000/api/exercises/create', payload);
      
      // --- BƯỚC 3: XỬ LÝ KẾT QUẢ ---
      if (res.data.success) {
        addLog("🤖 AI Check: Hợp lệ (Clean Content)");
        addLog(`📦 IPFS Upload: Thành công (Hash: ${res.data.ipfs_hash.slice(0, 10)}...)`);
        addLog("🎉 Hoàn tất: Bài tập đã lên sóng!");
        setStatus("success");
        showToast('success', "Đăng bài thành công!");
      } else {
        addLog(`❌ AI TỪ CHỐI: ${res.data.message}`);
        setStatus("error");
        showToast('error', res.data.message);
      }

    } catch (err) {
      console.error(err);
      // Xử lý lỗi chi tiết
      let errorMsg = "Lỗi không xác định";
      if (err.code === 'ACTION_REJECTED') {
          errorMsg = "Bạn đã từ chối ký xác nhận trên ví.";
      } else if (err.response && err.response.data) {
          errorMsg = err.response.data.message || err.response.data.error;
      } else {
          errorMsg = err.message;
      }

      addLog(`❌ LỖI: ${errorMsg}`);
      setStatus("error");
      showToast('error', errorMsg);
    }
  };

  return (
    <div className="pt-28 pb-10 px-6 min-h-screen flex justify-center">
      <div className="w-full max-w-4xl grid grid-cols-1 md:grid-cols-2 gap-8">
        
        {/* Cột trái: Form */}
        <div className="glass-panel p-8 animate-fade-in-up">
          <div className="mb-6">
            <h2 className="text-3xl font-heading font-bold text-white">Creator Studio</h2>
            <p className="text-gray-400">Tạo nội dung kiếm tiền (Create-to-Earn)</p>
          </div>
          
          <Form 
            schema={schema} 
            uiSchema={uiSchema} 
            validator={validator} 
            onSubmit={onSubmit}
            className="rjsf-dark"
          >
            <button 
              type="submit" 
              disabled={status === 'processing'}
              className={`w-full mt-6 py-3 rounded-xl font-bold text-white transition-all ${
                status === 'processing' ? 'bg-gray-600 cursor-wait' : 'btn-gradient shadow-lg hover:scale-105'
              }`}
            >
              {status === 'processing' ? 'Đang xử lý...' : '🚀 Ký & Gửi Kiểm Duyệt'}
            </button>
          </Form>
        </div>

        {/* Cột phải: Log Real-time */}
        <div className="flex flex-col gap-6 animate-fade-in-up" style={{ animationDelay: '0.2s' }}>
          <div className="glass-panel p-6 border-l-4 border-indigo-500 h-full relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-20"><span className="text-6xl">🤖</span></div>
            <h3 className="text-xl font-bold text-white mb-4">AI Moderation Log</h3>
            
            <div className="bg-black/40 rounded-lg p-4 h-64 overflow-y-auto font-mono text-sm border border-white/5 shadow-inner">
              {logs.length === 0 ? (
                <p className="text-gray-500 italic">...Chờ lệnh từ ví của bạn...</p>
              ) : (
                logs.map((log, idx) => (
                  <div key={idx} className={`mb-3 pb-2 border-b border-white/5 last:border-0 ${
                    log.includes('❌') ? 'text-red-400' : 
                    log.includes('✅') ? 'text-emerald-400' : 
                    log.includes('🎉') ? 'text-yellow-300 font-bold' : 
                    log.includes('🔐') ? 'text-blue-300' : 'text-gray-300'
                  }`}>
                    <span className="opacity-50 mr-2 text-xs">[{new Date().toLocaleTimeString()}]</span>
                    {log}
                  </div>
                ))
              )}
              {status === 'processing' && (
                <div className="animate-pulse text-indigo-400 mt-2">_ System is processing...</div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreatorStudio;
